, {"id": "f4dbf63c-0e63-4f4e-ac51-a3fffa1d490f", "type": "subtopic", "title": "Visual thinking", "children": [{"id": "2a8caf9c-6647-40bc-8a02-1114a2173c27", "type": "concept", "title": "Thumbnails, maps, diagrams, notations, and alternatives"}, {"id": "6c1c4ac6-eb11-4f42-b067-18d0e6459e20", "type": "concept", "title": "Drawing before language"}, {"id": "8c05a82d-b495-46ac-ae01-b2fd642df65d", "type": "concept", "title": "From study to project"}], "description": "Students connect drawing to problem solving and idea generation."}]}, {"id": "72891fcb-18f8-4b87-b6b9-d82a689e735d", "type": "topic", "title": "Line, Gesture, Mark-Making, Tone, Surface, Erasure, and Material Control", "description": "This module deepens technical control of marks while keeping gesture, sensitivity, risk, and material discovery alive.", "children": [{"id": "f31bb466-8eef-48a3-afe4-3830f048d865", "type": "subtopic", "title": "Line and gesture", "children": [{"id": "7e06fa33-0461-4282-b75a-079c89bae1f7", "type": "concept", "title": "Contour, cross-contour, searching line, calligraphic line, and weighted line"}, {"id": "c68a1b3a-0e92-498a-b2f9-7939876337ec", "type": "concept", "title": "Speed, pressure, rhythm, and touch"}, {"id": "3923ba98-7605-424a-86ec-87f8f3cf6d60", "type": "concept", "title": "Gesture as movement record"}], "description": "Students develop expressive and structural fluency with line."}, {"id": "9efa1c34-35a8-4059-9668-d2eeae732bb4", "type": "subtopic", "title": "Tone and surface", "children": [{"id": "5e75b923-b278-426e-846e-91c0be5af500", "type": "concept", "title": "Hatching, smudging, wash, stipple, layering, and value scales"}, {"id": "e3840ca1-1559-4f6e-a165-09d89b855e5c", "type": "concept", "title": "Paper tooth, ground, absorption, and surface preparation"}, {"id": "58a617a3-6882-4894-8f54-e723a5bbd4bf", "type": "concept", "title": "Atmospheric depth and contrast"}], "description": "The gist is to control light, weight, atmosphere, and material density."}, {"id": "e4