update public.learning_paths
set
  title = 'Drawing II',
  goal = 'Drawing II',
  summary = 'Students treat drawing as a rigorous way to perceive, analyze, remember, propose, and think through visual problems, while deepening control of line, gesture, tone, surface, and erasure. The course strengthens observation, perspective, mixed media, scale, color, figure, and anatomy, then extends drawing into memory, movement, scores, conceptual systems, finished work, contemporary practice, critique, series development, and a portfolio-ready capstone.',
