ious."}, {"id": "f4dbf63c-0e63-4f4e-ac51-a3fffa1d490f", "type": "subtopic", "title": "Visual thinking", "children": [{"id": "2a8caf9c-6647-40bc-8a02-1114a2173c27", "type": "concept", "title": "Thumbnails, maps, diagrams, notations, and alternatives"}, {"id": "6c1c4ac6-eb11-4f42-b067-18d0e6459e20", "type": "concept", "title": "Drawing before language"}, {"id": "8c05a82d-b495-46ac-ae01-b2fd642df65d", "type": "concept", "title": "From study to project"}], "description": "Students connect drawing to problem solving and idea generation."}]}, {"id": "72891fcb-18f8-4b87-b6b9-d82a689e735d", "type": "topic", "title": "Line, Gesture, Mark-Making, Tone, Surface, Erasure, and Material Control", "description": "This module deepens technical control of marks while keeping gesture, sensitivity, risk, and material discovery alive.", "children": [{"id": "f31bb466-8eef-48a3-afe4-3830f048d865", "type": "subtopic", "title": "Line and gesture", "children": [{"id": "7e06fa33-0461-4282-b75a-079c89bae1f7", "type": "concept", "title": "Contour, cross-contour, searching line, calligraphic line, and weighted line"}, {"id": "c68a1b3a-0e92-498a-b2f9-7939876337ec", "type": "concept", "title": "Speed, pressure, rhythm, and touch"}, {"id": "3923ba98-7605-424a-86ec-87f8f3cf6d60", "type": "concept", "title": "Gesture as movement record"}], "description": "Students develop expressive and structural fluency with line."}, {"id": "9efa1c34-35a8-4059-9668-d2eeae732bb4", "type": "subtopic", "title": "Tone and surface", "children": [{"id": "5e75b923-b278-426e-846e-91c0be5af500", "type": "concept", "title": "Hatching, smudging, wash, stipple, layering, and value scales"}, {"id": "e3840ca1-1559-4f6e-a165-09d89b855e5c", "type": "concept", "title": "Paper tooth, ground, absorption, and surface preparation"}, {"id": "58a617a3-6882-4894-8f54-e723a5bbd4bf", "type": "concept", "title": "Atmospheric depth and contrast"}], "description": "The gist is to control light, weight, atmosphere, and material density."}, {"id": "e446a86c-7f4a-4918-be4b-7a70b8b7eaa8", "type": "subtopic", "title": "Erasure and revision", "children": [{"id": "da635aa8-2fd5-4e0b-9808-b561706721f4", "type": "concept", "title": "Subtractive drawing, lifting, scraping, masking, correction, and ghost images"}, {"id": "8e2c5a5a-4b0f-4945-9113-21689ced046e", "type": "concept", "title": "Pentimento and process visibility"}, {"id": "9b5eb1d2-1ea9-4041-aea2-d78b71d9c6d6", "type": "concept", "title": "Control versus accident"}], "description": "Students treat erasure as an active drawing method."}]}, {"id": "59149dec-6b30-476f-b2de-2a739c42fdbd", "type": "topic", "title": "Observation, Contour, Form, Space, Perspective, and Constructive Drawing", "description": "Students strengthen observational drawing by connecting what they see to structure, proportion, volume, space, and perspective.", "children": [{"id": "9c97e9a5-a8df-454b-a5ba-bff4e736652c", "type": "subtopic", "title": "Contour and form", "children": [{"id": "b9b5bb38-5415-4a21-abeb-eb78c71a8e2a", "type": "concept", "title": "Blind contour, modified contour, cross-contour, and planar analysis"}, {"id": "7b48e50b-3947-41e2-9430-78167ed7b233", "type": "concept", "title": "Organic and geometric forms"}, {"id": "2a44d596-1c47-4b19-8163-b5255a84c059", "type": "concept", "title": "Volume through line and value"}], "description": "Students connect edge observation to volume and structure."}, {"id": "0b448d91-2854-4cb8-9132-11504d05931a", "type": "subtopic", "title": "Perspective and space", "children": [{"id": "05053509-e05c-443b-8687-5fdf7c518051", "type": "concept", "title": "One-point, two-point, atmospheric perspective, scale, overlap, and foreshortening"}, {"id": "e429f8df-38d0-40e8-82dd-dd071e749d9b", "type": "concept", "title": "Interior and exterior space"}, {"id": "38b12db0-ed53-4ced-94db-8797c0a163cd", "type": "concept", "title": "Spatial errors and correction strategies"}], "description": "The point is to build believable spatial worlds."}, {"id": "e2297598-23cf-49ce-8844-a302ec22c1fe", "type": "subtopic", "title": "Constructive drawing", "children": [{"id": "d887cf59-2b07-4a3b-ab91-572a1eb31601", "type": "concept", "title": "Boxes, cylinders, spheres, axes, envelopes, and proportional scaffolds"}, {"id": "9fd0cc72-8b52-486a-89ba-cd0b56e646bb", "type": "concept", "title": "Still life, figure, object, and environment construction"}, {"id": "32d644bf-15d8-43fa-827c-69edde7f092e", "type": "concept", "title": "Drawing from observation and invention"}], "description": "Students learn to draw complex subjects through underlying structure."}]}, {"id": "b2202258-e71b-4102-a3f0-38d05e51abcc", "type": "topic", "title": "Mixed Media Drawing: Graphite, Charcoal, Ink, Pigment, Transfer, Collage, and Digital Tools", "description": "This topic expands drawing media so students can choose materials for conceptual and formal reasons.", "children": [{"id": "8f7a3804-dd98-4e7d-9254-2a4f935e746b", "type": "subtopic", "title": "Material vocabulary", "children": [{"id": "694d35f4-0968-4eb4-85cd-f959b49a3e8b", "type": "concept", "title": "Graphite, charcoal, conte, ink, pastel, colored pencil, watercolor, gouache, and marker"}, {"id": "03ca7352-b6ba-4bbe-8eca-573725878d06", "type": "concept", "title": "Dry versus wet media"}, {"id": "da61f822-a589-4e57-991b-d9434be9711e", "type": "concept", "title": "Archival concerns and layering"}], "description": "Students learn what different media can do and why they might choose them."}, {"id": "eeedb7f9-0d96-45be-9772-599fcf3f0e00", "type": "subtopic", "title": "Collage and transfer", "children": [{"id": "d7a7d16a-587b-4078-bb24-dbe94e7f2fb3", "type": "concept", "title": "Cut paper, image transfer, tracing, photocopy, transparency, and montage"}, {"id": "8ee70f79-1041-4c0e-b922-ee66ec94855e", "type": "concept", "title": "Texture, scale shift, and juxtaposition"}, {"id": "08ff68ab-b207-42dd-96c6-057389ac3e87", "type": "concept", "title": "Source ethics and appropriation"}], "description": "The gist is to combine found and made marks meaningfully."}, {"id": "2504e093-4b9d-4265-9f7b-9465dc78602d", "type": "subtopic", "title": "Digital extension", "children": [{"id": "4c5de606-c320-4016-b009-88986de2427a", "type": "concept", "title": "Scanning, cleanup, layering, tablet drawing, projection, and print output"}, {"id": "e47238f7-8238-4b40-8f6e-08ba6bd195b8", "type": "concept", "title": "Analog-digital loops"}, {"id": "2ea3f4a0-8b76-4c4c-a0df-ff7d7acaff18", "type": "concept", "title": "File quality and documentation"}], "description": "Students use digital tools as part of drawing rather than a replacement for it."}]}, {"id": "3e6a2927-46e8-498a-87b1-bf18f7f77706", "type": "topic", "title": "Large-Scale Drawing: Body, Duration, Repetition, Installation, and Physical Process", "description": "Students learn how scale changes gesture, time, composition, surface, and viewer experience.", "children": [{"id": "9c4f1747-efb9-4240-b051-79c2d176b617", "type": "subtopic", "title": "Scale and body", "children": [{"id": "832db36e-9fb6-4cd3-82b0-5b71970d2b70", "type": "concept", "title": "Arm movement, full-body gesture, reach, stamina, and physical rhythm"}, {"id": "0693e1bf-a949-4871-bc65-355991a75501", "type": "concept", "title": "Viewing distance and immersive presence"}, {"id": "ebeeefec-5297-4ead-882e-baa8465e23f7", "type": "concept", "title": "Paper rolls, wall drawing, floor drawing, and installation supports"}], "description": "Students learn how large formats change movement and decision-making."}, {"id": "94c4a0a7-0be7-472e-920f-1da02c8381d4", "type": "subtopic", "title": "Duration and repetition", "children": [{"id": "c10614ea-8821-4495-ad60-95ccbe8bda2e", "type": "concept", "title": "Accumulation, serial marks, grids, endurance, daily practice, and process rules"}, {"id": "1b35a097-aa68-4803-b5d4-aeb8d16c5d67", "type": "concept", "title": "Repetition as variation"}, {"id": "131dd17a-01db-4b46-bba1-33eea7c5c507", "type": "concept", "title": "Time-based documentation"}], "description": "The point is to use time as part of drawing."}, {"id": "830ec616-4c8a-4d4b-99d2-06dcee95f2b4", "type": "subtopic", "title": "Installation thinking", "children": [{"id": "25932b0c-34b9-4850-af5b-60b9d3a2317b", "type": "concept", "title": "Wall, corner, floor, suspended, projected, and site-responsive drawings"}, {"id": "808bac17-b716-4766-ac34-d025e95a8e30", "type": "concept", "title": "Viewer movement and spatial encounter"}, {"id": "319dad4f-e735-463a-b6b4-0644da529ad2", "type": "concept", "title": "Mounting, lighting, and presentation"}], "description": "Students consider how drawings inhabit space."}]}, {"id": "0bff3062-f1f4-4427-a5f9-c5a7ae2caeb8", "type": "topic", "title": "Color Drawing: Pastel, Colored Pencil, Ink, Wash, Chromatic Structure, and Mood", "description": "This module introduces color as structure, light, temperature, emotion, rhythm, and material event within drawing.", "children": [{"id": "db510bc7-c9b9-4f53-a17f-a4d6a61ad373", "type": "subtopic", "title": "Color materials", "children": [{"id": "7b472a3e-2ced-42ec-ad23-1cf47a55fd25", "type": "concept", "title": "Pastel, colored pencil, ink wash, watercolor, gouache, and mixed dry/wet approaches"}, {"id": "ac25caa6-5ecd-4173-b330-bbda2123bc42", "type": "concept", "title": "Layering, blending, fixative, saturation, and opacity"}, {"id": "31a60ea9-1378-407e-b280-bd9329bdc6f3", "type": "concept", "title": "Paper color and ground"}], "description": "Students gain control over common color drawing media."}, {"id": "293769da-06a7-43b3-b0d6-e302624ec97e", "type": "subtopic", "title": "Color structure", "children": [{"id": "d5f1a841-0cc8-43de-a99e-009d0e962fa5", "type": "concept", "title": "Hue, value, chroma, temperature, complement, harmony, and contrast"}, {"id": "9939533a-d7ff-4bdb-ba2a-0360eb1c5dda", "type": "concept", "title": "Local color versus expressive color"}, {"id": "cd9394fa-a6b4-40a6-a6ed-91cbd7b2bfe5", "type": "concept", "title": "Color as space and emphasis"}], "description": "The gist is to make color organize the drawing."}, {"id": "fe19ba6a-02a8-496d-a28d-73ecaea84bff", "type": "subtopic", "title": "Mood and meaning", "children": [{"id": "0ab0225a-22a7-4134-a587-09f10c5305f1", "type": "concept", "title": "Atmosphere, symbolic color, memory, identity, and narrative tone"}, {"id": "2a6eef7a-b671-4bd0-ae22-45a433ea47a5", "type": "concept", "title": "Restraint and palette design"}, {"id": "2dfadad8-a8aa-4b5c-9abc-0f24835ac5e8", "type": "concept", "title": "Color critique vocabulary"}], "description": "Students use color to shape emotional and conceptual effect."}]}, {"id": "62543a00-5180-4051-85e6-7bd4d6ec028d", "type": "topic", "title": "Figure Drawing from Life: Gesture, Proportion, Movement, Structure, and Presence", "description": "Students develop a responsive figure-drawing practice rooted in looking, time, anatomy, movement, and embodied presence.", "children": [{"id": "77fc0978-6176-4740-9c37-afea91686806", "type": "subtopic", "title": "Gesture and pose", "children": [{"id": "aca9b4cb-3694-40e2-91fe-e9b6a3d619af", "type": "concept", "title": "Line of action, weight, balance, rhythm, and timed poses"}, {"id": "06c5196c-20a6-4bdc-a27b-3e2233948d40", "type": "concept", "title": "Short pose to long pose development"}, {"id": "111f0e49-d94c-4c3d-bee1-ee72466a2b9b", "type": "concept", "title": "Movement and compression"}], "description": "Students learn to capture the living action of the figure."}, {"id": "2277a7da-f135-42dd-8d84-a53deabd9444", "type": "subtopic", "title": "Proportion and structure", "children": [{"id": "1403662e-6bdb-4a36-a63b-b411df54f015", "type": "concept", "title": "Head units, landmarks, torso masses, pelvis, limbs, hands, feet, and head structure"}, {"id": "143df263-d9e2-4e2d-a5f1-3cbfcb7af184", "type": "concept", "title": "Foreshortening and proportional correction"}, {"id": "063331ec-deb0-49e5-8ef1-6c30744322e0", "type": "concept", "title": "Structure without stiffness"}], "description": "The point is to balance observation with anatomical scaffolding."}, {"id": "68d06756-7d2c-46f3-a5f5-39475c773a33", "type": "subtopic", "title": "Presence and expression", "children": [{"id": "b25fd553-b71f-45bd-ae5e-2e435c9d5152", "type": "concept", "title": "Identity, posture, vulnerability, consent, gaze, and respect"}, {"id": "781143e3-2be2-4007-a95d-1cf9374125dc", "type": "concept", "title": "Model etiquette and studio professionalism"}, {"id": "2bdd23ee-0bc5-473a-a7ea-62b1cb4fe87d", "type": "concept", "title": "Figure as subject, form, and relation"}], "description": "Students consider figure drawing as more than anatomy exercise."}]}, {"id": "2955f2ac-7553-4911-b199-de828880c604", "type": "topic", "title": "Anatomy for Artists: Skeleton, Muscles, Planes, Landmarks, Hands, Feet, and Portrait Structure", "description": "This topic gives students structural knowledge that supports expressive and accurate figure work.", "children": [{"id": "ca731f87-43db-4fe1-aed5-a903b6534284", "type": "subtopic", "title": "Skeletal landmarks", "children": [{"id": "0aa7708c-6da0-4341-83b8-78dcbff78319", "type": "concept", "title": "Skull, spine, rib cage, pelvis, scapula, clavicle, joints, and major bony landmarks"}, {"id": "51f3a0e7-1092-4fe3-a92d-18ef9040a2a9", "type": "concept", "title": "Balance, tilt, and alignment"}, {"id": "d4d87cf1-4c41-4152-80b9-303c333a19de", "type": "concept", "title": "Anatomy visible on the surface"}], "description": "Students learn the durable structure under surface form."}, {"id": "ac29f2a5-218b-498b-8a33-4c85487152be", "type": "subtopic", "title": "Muscle groups and planes", "children": [{"id": "e050c8b8-2a6a-499f-8c09-ddde3c0b2495", "type": "concept", "title": "Torso, shoulder, arm, leg, neck, face, and back muscle groups"}, {"id": "fc941a2c-5dc4-447b-82f5-43473055eb5f", "type": "concept", "title": "Planes, masses, tendons, and compression"}, {"id": "078624c0-e29c-4525-90a0-b90d79f16b79", "type": "concept", "title": "Anatomy for movement and weight"}], "description": "The gist is to simplify anatomy into usable drawing knowledge."}, {"id": "1aa43608-ee7e-4cef-9e16-df0281bc8d4a", "type": "subtopic", "title": "Hands, feet, and portrait", "children": [{"id": "9558b344-6ab0-4847-8817-d94082681bff", "type": "concept", "title": "Hand construction, foot construction, head planes, features, and expression"}, {"id": "f5c94cf0-ff10-4ec6-a4d9-bf024cd1d4ed", "type": "concept", "title": "Gesture and proportion in extremities"}, {"id": "fb274237-129e-4eee-be9e-aadaec06818a", "type": "concept", "title": "Common distortions and corrections"}], "description": "Students focus on forms that often reveal weak structure."}]}, {"id": "5d460b73-cdb0-406f-8e91-d8fb6abf8389", "type": "topic", "title": "Drawing from Memory, Body, Movement, Score, Diagram, and Performance", "description": "Students move beyond direct observation into drawing as memory, notation, action, instruction, and performative trace.", "children": [{"id": "d9b54cae-a103-4759-b811-58b31ea67b77", "type": "subtopic", "title": "Memory drawing", "children": [{"id": "3dc3a99c-27f1-43c7-bbf6-935d9ced88c8", "type": "concept", "title": "Memory maps, emotional space, dream imagery, and reconstructed scenes"}, {"id": "1aaf4870-2ac5-416b-8dab-3af5bb256946", "type": "concept", "title": "Distortion as meaning"}, {"id": "aac42261-19f9-4a12-8c87-98bdd1e3e82c", "type": "concept", "title": "Observation stored in the body"}], "description": "Students draw from remembered experience rather than direct sight."}, {"id": "6180e576-98fc-4b00-bf05-36e7c9a2c25c", "type": "subtopic", "title": "Body and movement", "children": [{"id": "1c3a8049-2213-424d-a2eb-85a0e163fb8d", "type": "concept", "title": "Walking lines, breath marks, repetitive motions, dance, reach, and pressure"}, {"id": "9a1027f8-b2b4-4a86-b6d3-08494926ef66", "type": "concept", "title": "Drawing tools attached to body movement"}, {"id": "fe86e96e-d9b9-4e71-9ec8-0a9e0d8d0b8a", "type": "concept", "title": "Process documentation"}], "description": "The point is to draw action as trace and performance."}, {"id": "68945491-ee30-4b2d-94b8-c7dc128dfe32", "type": "subtopic", "title": "Score-based drawing", "children": [{"id": "5f8e0d16-9ab0-46f0-943e-59260a53439c", "type": "concept", "title": "Rules, prompts, chance operations, diagrams, maps, and time limits"}, {"id": "e8456c0a-925c-4a63-9460-8cd3f8453787", "type": "concept", "title": "Instruction as artwork"}, {"id": "ebd925de-fdfb-4e43-bd7f-870e9e974a12", "type": "concept", "title": "Repeatability and variation"}], "description": "Students use instructions and systems to generate work."}]}, {"id": "fa69c4bc-fc6b-43f8-8de2-a1d876b6f7a2", "type": "topic", "title": "Conceptual Drawing: Idea, Metaphor, System, Constraint, Text, Time, and Research", "description": "This module treats drawing as conceptual inquiry, using constraints, systems, language, and research to generate meaning.", "children": [{"id": "7d02b11b-ce7b-46bd-92c8-f5afb4ee271b", "type": "subtopic", "title": "Idea-driven drawing", "children": [{"id": "bc2446f8-f48e-412d-8197-31fb84de2ce5", "type": "concept", "title": "Metaphor, symbol, archive, index, map, body, and social issue"}, {"id": "7a42ae9f-9bb0-4625-90a3-820f8eddaaa1", "type": "concept", "title": "Drawing as question or proposition"}, {"id": "d96aecec-7f2b-489d-8154-d6f49eebd4da", "type": "concept", "title": "Avoiding illustration of an idea too literally"}], "description": "Students learn how concept can shape material decisions."}, {"id": "2d7d889e-836f-4296-a040-48334138bad9", "type": "subtopic", "title": "Systems and constraints", "children": [{"id": "1faad09d-667c-4e4b-a79c-1512f39b6713", "type": "concept", "title": "Rules, grids, accumulation, repetition, data, measurement, and transformation"}, {"id": "9c7f1851-a636-42d7-befc-b720bb1204b4", "type": "concept", "title": "Constraint as creative engine"}, {"id": "d66e7da2-83a0-4642-9dbd-743c7c690219", "type": "concept", "title": "System failure and surprise"}], "description": "The gist is to generate work through chosen limits."}, {"id": "f453405d-0e2a-4cd8-a359-ecde29e5de09", "type": "subtopic", "title": "Research-based drawing", "children": [{"id": "bb8c8769-3c0d-4857-a1a5-fa9ba2c42380", "type": "concept", "title": "Artist research, historical images, field notes, interviews, objects, and archives"}, {"id": "affb31be-e6d1-4882-ad0a-0539c2ec3a70", "type": "concept", "title": "Citation and source transformation"}, {"id": "98a77a6f-065d-4f53-8499-2f919132e66c", "type": "concept", "title": "Ethics of borrowed material"}], "description": "Students connect drawing to external inquiry."}]}, {"id": "16128667-bc2c-4d98-b995-265ba85cc86c", "type": "topic", "title": "Drawing as Final Work: Composition, Series, Editing, Scale, Craft, and Exhibition", "description": "Students learn how drawings become finished works through sustained decisions about composition, material, sequence, and presentation.", "children": [{"id": "be676084-5dbd-4b05-9dbd-4c3e293c5b6d", "type": "subtopic", "title": "Composition and resolution", "children": [{"id": "a3c54452-c5ec-405f-bef5-601e4ef29149", "type": "concept", "title": "Balance, emphasis, rhythm, edge, tension, silence, density, and focal structure"}, {"id": "8ea29c51-d48a-4160-81c5-01c2b366faab", "type": "concept", "title": "Resolution versus overworking"}, {"id": "a53f5036-b438-4536-81d6-2ee1667af448", "type": "concept", "title": "Criteria for completion"}], "description": "Students learn how a drawing becomes finished."}, {"id": "e6922231-f95e-4662-b86c-fb4d0505f9a9", "type": "subtopic", "title": "Editing and sequence", "children": [{"id": "b93bc342-7796-493a-abec-2a7c986e28c2", "type": "concept", "title": "Rejects, studies, variations, groupings, order, and pacing"}, {"id": "9fcac874-46b5-431d-aa56-69cf7411e923", "type": "concept", "title": "Diptych, triptych, grid, wall sequence, and book format"}, {"id": "450501d0-b771-4d66-9f5a-3de9e2d7730e", "type": "concept", "title": "Series logic"}], "description": "